INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 1, 11, "シズルさまにエリコさま、\nどうかされたのですか？", 905, 10, 19050041, 107611, 0.5, 0, 0);
