INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", 0, 21, "vo_fpc_30403", 944, "", 19440029, "vo_fpc", "", "", "");
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 1, 11, "あら、タマキさんじゃない。\nこんなところで何やってるの？", 944, 10, 19440030, 126811, 1, 0, 0);
INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES ("", "", 91, "", 944, "", 19440031, 0, "", "", "");
