INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 1, 11, "なんだ、ユカリだったかにゃ。\n何ってもちろん商売にゃ！", 944, 10, 19440033, 107911, 1, 0, 0);
