INSERT INTO `v1_96f23f811a830688c5cc539b1e18bf680c6eb752029cac1528eb1afabff8b19d` VALUES (0, 1, 11, "こんなに人がいっぱいいる商機、\n見逃すわけにはいかないにゃ！", 944, 10, 19440038, 107911, 1, 0, 0);
